export const STATIC_COPY = {"Analyse (۵ دقیقه)":{"en":"Analysis (5 minutes)","de":"Analyse (5 Minuten)"},"Aufgaben lösen (۱۵ دقیقه): کلمات کلیدی ← پاراگراف ← جمله پاسخ ← مقایسه گزینه‌ها ← انتخاب.":{"en":"Aufgaben lösen (15 minutes): keywords → paragraph → answer sentence → compare options → choose.","de":"Aufgaben lösen (15 Minuten): Stichworte → Absatz → Antwortsatz → Optionen vergleichen → wählen."},"Erneutes Hören (۱۰ دقیقه): بدون متن دوباره گوش بده.":{"en":"Erneutes Hören (10 minutes): Listen again without text.","de":"Erneutes Hören (10 Minuten): Nochmals ohne Text anhören."},"Fehleranalyse (۱۰ دقیقه): دسته‌بندی اشتباهات و خلاصه یک‌خطی.":{"en":"Fehleranalyse (10 minutes): Error classification and one-line summary.","de":"Fehleranalyse (10 Minuten): Fehlerklassifizierung und einzeilige Zusammenfassung."},"Fehlerprotokoll (۵ دقیقه): حداکثر سه اشتباه مهم با اصلاح و علت":{"en":"Fehlerprotokoll (5 minutes): maximum three important errors with correction and cause","de":"Fehlerprotokoll (5 Minuten): maximal drei wichtige Fehler mit Korrektur und Ursache"},"Gliederung (۵ دقیقه)":{"en":"Gliederung (5 minutes)","de":"Gliederung (5 Minuten)"},"Globales Hören (۵ دقیقه): بدون متن گوش بده؛ موضوع، مسئله و هدف گوینده.":{"en":"Globales Hören (5 minutes): listen without text; The speaker's subject, problem and goal.","de":"Globales Hören (5 Minuten): Hören ohne Text; Thema, Problem und Ziel des Redners."},"Grammatik & Wortschatz · ۲۵ دقیقه":{"en":"Grammar & vocabulary · 25 minutes","de":"Grammatik & Wortschatz · 25 Minuten"},"Hören · ۶۰ دقیقه · اولویت اصلی":{"en":"Listening · 60 minutes · Main priority","de":"Hören · 60 Minuten · höchste Priorität"},"Intensives Lesen (۱۵ دقیقه): برای هر پاراگراف یک جمله مفهوم اصلی؛ بدون ترجمه کلمه‌به‌کلمه.":{"en":"Intensive Reading (15 minutes): for each paragraph, one main concept sentence; No word for word translation.","de":"Intensives Lesen (15 Minuten): für jeden Absatz ein Hauptkonzeptsatz; Keine Wort-für-Wort-Übersetzung."},"Korrektur (۱۰ دقیقه): Grammatik, Wortschatz, Konnektoren, Struktur, Aufgabenbezug":{"de":"Korrektur (10 Minuten): Grammatik, Wortschatz, Konnektoren, Struktur, Aufgabenbezug","en":"Korrektur (10 minutes): Grammatik, Wortschatz, Konnektoren, Struktur, Aufgabenbezug"},"Lesen · ۴۵ دقیقه":{"en":"Reading · 45 minutes","de":"Lesen · 45 Minuten"},"Phase 1 · تثبیت پایه‌ها":{"en":"Phase 1 · Building foundations","de":"Phase 1 · Grundlagen festigen"},"Phase 2 · تقویت مهارت آزمونی":{"en":"Phase 2 · Strengthening exam skills","de":"Phase 2 · Prüfungskompetenzen stärken"},"Phase 3 · شبیه‌سازی آزمون":{"en":"Phase 3 · Exam simulation","de":"Phase 3 · Prüfungssimulation"},"Schreiben (۲۵ دقیقه): هر پاراگراف = Behauptung + Begründung + Beispiel + Konsequenz":{"en":"Schreiben (25 minutes): each paragraph = Behauptung + Begründung + Beispiel + Konsequenz","de":"Schreiben (25 Minuten): jeder Absatz = Behauptung + Begründung + Beispiel + Konsequenz"},"Schreiben · ۵۰ دقیقه":{"en":"Writing · 50 minutes","de":"Schreiben · 50 Minuten"},"Selektives Hören (۱۰ دقیقه): اعداد، دلایل، مزایا، معایب، مثال‌ها و نتیجه‌گیری‌ها را کلیدواژه‌ای یادداشت کن.":{"en":"Selektives Hören (10 minutes): Keynote numbers, reasons, advantages, disadvantages, examples and conclusions.","de":"Selektives Hören (10 Minuten): Keynote-Nummern, Gründe, Vor- und Nachteile, Beispiele und Schlussfolgerungen."},"Sprechen · ۳۵ دقیقه":{"en":"Speaking · 35 minutes","de":"Sprechen · 35 Minuten"},"Sprechen با زمان مشخص (توقف خودکار ضبط)":{"en":"Sprechen with specified time (auto stop recording)","de":"Sprechen mit vorgegebener Zeit (Aufnahme automatisch stoppen)"},"Transkription und Analyse (۱۵ دقیقه): بخش‌های نامفهوم را با متن بررسی کن و اشتباهات را در سه دسته ثبت کن.":{"de":"Transkription und Analyse (15 Minuten): Überprüfen Sie die unklaren Teile mit dem Text und notieren Sie die Fehler in drei Kategorien.","en":"Transcription und Analyze (15 minutes): check the unclear parts with the text and record the mistakes in three categories."},"Wiederholung · ۲۵ دقیقه · Active Recall":{"en":"Review · 25 minutes · active recall","de":"Wiederholung · 25 Minuten · aktives Abrufen"},"Zusammenfassung (۲۰ دقیقه): بدون متن به آلمانی بازگو کن و صدایت را ضبط و بررسی کن.":{"en":"Zusammenfassung (20 minutes): Recite in German without text and record and check your voice.","de":"Zusammenfassung (20 Minuten): Rezitieren Sie auf Deutsch ohne Text und nehmen Sie Ihre Stimme auf und überprüfen Sie sie."},"Überblick (۵ دقیقه): عنوان و تیترها، پیش‌بینی محتوا.":{"en":"Overview (5 minutes): title and headings, content preview.","de":"Überblick (5 Minuten): Titel und Überschriften, Inhaltsvorschau."},"آزمون از خود بدون جزوه (۵)":{"en":"Self-test without booklet (5)","de":"Selbsttest ohne Heft (5)"},"آزمون‌های کامل (بخش «آزمون» در منوی کناری)":{"en":"Complete tests (\"Test\" section in the side menu)","de":"Komplette Tests (Abschnitt „Test“ im Seitenmenü)"},"آماده‌سازی (۵ دقیقه): فقط کلمات کلیدی، جمله کامل ننویس.":{"en":"Preparation (5 minutes): Only key words, don't write complete sentences.","de":"Vorbereitung (5 Minuten): Nur Schlüsselwörter, keine ganzen Sätze schreiben."},"اجرای مجدد (۱۵ دقیقه): بدون یادداشت؛ اگر جمله‌ای یادت رفت با ساختار دیگری منظور را برسان.":{"en":"Repeat performance (15 minutes): without notes; If you forget a sentence, use another structure to convey the meaning.","de":"Wiederholung (15 Minuten): ohne Noten; Wenn Sie einen Satz vergessen, verwenden Sie eine andere Struktur, um die Bedeutung zu vermitteln."},"ارائه موضوع":{"en":"Presentation of the subject","de":"Vorstellung des Themas"},"ارزیابی":{"en":"Evaluation","de":"Auswertung"},"ارزیابی Sprechen (داخل همین برنامه)":{"en":"Sprechen evaluation (within the same app)","de":"Sprechen-Auswertung (innerhalb der gleichen App)"},"ارزیابی چهار مهارت":{"en":"Assessment of four skills","de":"Bewertung von vier Fähigkeiten"},"از این می‌توان نتیجه گرفت که":{"en":"From this we can conclude that","de":"Daraus können wir schließen"},"از هفته ۷ به بعد":{"de":"Ab Woche 7","en":"From week 7 onwards"},"استدلال‌های شخص را بی‌طرف و با گفتار غیرمستقیم (Konjunktiv I) بازگو کن، سپس نظر کوتاه خودت را بگو.":{"en":"Restate the person's arguments neutrally and in indirect speech (Konjunktiv I), then give your own brief opinion.","de":"Wiederholen Sie die Argumente der Person neutral und in indirekter Rede (Konjunktiv I) und geben Sie dann Ihre eigene kurze Meinung ab."},"اسم‌سازی و سبک اسمی (مهم برای Lesen و Schreiben)":{"de":"Substantivbildung und Nominalstil (wichtig für Lesen und Schreiben)","en":"Noun formation and nominal style (important for Lesen and Schreiben)"},"اشتباه رایج: استفاده از sein به‌جای werden در مجهول فرایندی؛ فراموش‌کردن werden در انتهای جمله با فعل وجهی.":{"en":"Common mistake: using sein instead of werden in the processional indefinite; Forgetting werden at the end of a sentence with a modal verb.","de":"Häufiger Fehler: Verwendung von „sein“ anstelle von „werden“ im Prozessions-Indefinite; Vergessen werden am Ende eines Satzes mit einem Modalverb."},"اشتباه رایج: استفاده هم‌زمان از würde و hätte در یک بخش جمله؛ Konjunktiv II برای Rat geben در Sprechen بسیار پرکاربرد است.":{"en":"Common mistake: using würde and hätte at the same time in the same part of the sentence; Konjunktiv II for Rat geben is very common in Sprechen.","de":"Häufiger Fehler: würde und hätte gleichzeitig im selben Satzteil verwendet; Konjunktiv II für Rat geben ist im Sprechen sehr verbreitet."},"اشتباه رایج: انتخاب حالت ضمیر موصولی بر اساس جمله اصلی؛ پایان صفت در Partizipialattribut.":{"en":"Common mistake: choosing the mode of relative pronoun based on the main sentence; Adjective ending in Partizipialattribute.","de":"Häufiger Fehler: Wahl des Modus des Relativpronomens basierend auf dem Hauptsatz; Adjektiv mit der Endung Partizipialattribute."},"اشتباه رایج: ترتیب کلمات بعد از desto (desto man hat ✗ → desto weniger Stress hat man ✓).":{"en":"Common mistake: word order after desto (desto man hat ✗ → desto weniger Stress hat man ✓).","de":"Häufiger Fehler: Wortreihenfolge nach desto (desto man hat ✗ → desto weniger Stress hat man ✓)."},"اشتباه رایج: تکرار مستقیم جمله‌ها بدون تغییر ضمیر و فعل؛ استفاده از ist به‌جای sei.":{"en":"Common mistake: direct repetition of sentences without changing pronouns and verbs; Use ist instead of sei.","de":"Häufiger Fehler: direkte Wiederholung von Sätzen ohne Änderung von Pronomen und Verben; Verwenden Sie ist anstelle von sei."},"اشتباه رایج: فراموش‌کردن حالت Genitiv بعد از اسم‌سازی (die Senkung die Kosten ✗ → der Kosten ✓).":{"en":"Common mistake: Forgetting the genitive case after noun formation (die Senkung die Kosten ✗ → der Kosten ✓).","de":"Häufiger Fehler: Vergessen des Genitivs nach der Substantivbildung (die Senkung die Kosten ✗ → der Kosten ✓)."},"اشتباه رایج: فعل را بعد از weil در جایگاه دوم گذاشتن (weil die Mieten sind gestiegen ✗). بعد از trotzdem/deshalb فعل بلافاصله می‌آید.":{"en":"Common mistake: putting the verb in the second position after weil (weil die Mieten sind gestiegen ✗). After trotzdem/deshalb comes the verb immediately.","de":"Häufiger Fehler: Setzen Sie das Verb an die zweite Position nach weil (weil die Mieten sind gestiegen ✗). Nach trotzdem/deshalb kommt das Verb sofort."},"اشتباه رایج: فعل نامناسب برای اسم (eine Entscheidung machen ✗ → treffen ✓).":{"en":"Common mistake: inappropriate verb for noun (eine Entscheidung machen ✗ → treffen ✓).","de":"Häufiger Fehler: unangemessenes Verb für Substantiv (eine Entscheidung machen ✗ → treffen ✓)."},"اشتباهات پرتکرار باید در Fehlerprotokoll ثبت شوند.":{"de":"Häufige Fehler sollten im Fehlerprotokoll erfasst werden.","en":"Frequent errors should be recorded in the Fehlerprotokoll."},"اقدام را خلاصه کن، دو مشکل مشخص را با دلیل نقد کن و یک پیشنهاد جایگزین واقع‌بینانه بده.":{"en":"Summarize the action, criticize two specific problems with reason, and propose a realistic alternative.","de":"Fassen Sie die Aktion zusammen, kritisieren Sie zwei spezifische Probleme mit Vernunft und schlagen Sie eine realistische Alternative vor."},"انواع سؤالات شفاهی":{"en":"Types of oral questions","de":"Arten von mündlichen Fragen"},"اگر بعد از چند بار شنیدن جمله‌ای را متوجه نشدی، به‌جای تکرار بی‌هدف، متن و ساختار گرامری آن را تحلیل کن.":{"en":"If you don't understand a sentence after hearing it a few times, instead of repeating it aimlessly, analyze its text and grammatical structure.","de":"Wenn Sie einen Satz nach mehrmaligem Hören nicht verstehen, sollten Sie ihn nicht ziellos wiederholen, sondern seinen Text und seine grammatikalische Struktur analysieren."},"بازگویی استدلال‌ها":{"en":"Retelling the arguments","de":"Die Argumente noch einmal erzählen"},"بازگویی محتوای روز قبل (۵)":{"en":"Retelling the content of the previous day (5)","de":"Den Inhalt des Vortages noch einmal erzählen (5)"},"بازگویی و ارائه":{"de":"Nacherzählung und Präsentation","en":"Retelling and presentation"},"برخلاف آن":{"en":"Contrary to that","de":"Im Gegensatz dazu"},"تثبیت مطالب از طریق بازیابی فعال.":{"de":"Inhaltsstabilisierung durch aktive Wiederherstellung.","en":"Content stabilization through active recovery."},"تحلیل اشتباهات (بخش «اشتباهات» در منوی کناری)":{"en":"Error analysis (\"Errors\" section in the side menu)","de":"Fehleranalyse (Bereich „Fehler“ im Seitenmenü)"},"تحلیل اشتباهات و مرور":{"en":"Error analysis and review","de":"Fehleranalyse und -überprüfung"},"تحلیل دقیق اشتباهات":{"en":"Detailed analysis of errors","de":"Detaillierte Fehleranalyse"},"تحلیل فایل صوتی و متن":{"en":"Audio and text file analysis","de":"Analyse von Audio- und Textdateien"},"ترکیب‌های فعل-اسم و حروف اضافه با Genitiv":{"de":"Verb-Nomen-Kombinationen und Präpositionen mit Genitiv","en":"Verb-Noun Combinations and Prepositions with Genitive"},"تقویت Hören":{"de":"Hören stärken","en":"Strengthen Hören"},"تقویت جمله‌سازی":{"en":"Improve sentence construction","de":"Satzbau verbessern"},"تمرکز بر مهارت‌های پایین‌تر از TDN 4":{"de":"Konzentrieren Sie sich auf Fähigkeiten unter TDN 4","en":"Focus on skills below TDN 4"},"تمرین Hören همراه Transkript":{"en":"Listening practice with transcript","de":"Hörübung mit Transkript"},"تمرین آزمونی (لینک رسمی پایین صفحه)":{"en":"Test practice (official link at the bottom of the page)","de":"Testpraxis (offizieller Link unten auf der Seite)"},"تمرین زمان‌دار":{"en":"Timed exercise","de":"Zeitgesteuerte Übung"},"تمرین زمان‌دار آزمون":{"en":"Timed practice test","de":"Zeitgesteuerter Übungstest"},"تمرین‌ها باید خروجی قابل‌اندازه‌گیری داشته باشند.":{"en":"Exercises should have a measurable output.","de":"Übungen sollten einen messbaren Output haben."},"توصیه دادن":{"en":"to advise","de":"zu beraten"},"تکرار آزمون‌های زمان‌دار":{"de":"Wiederholung zeitgesteuerter Tests","en":"Repetition of timed tests"},"جمعه":{"en":"Friday","de":"Freitag"},"جمله‌های علّی و ضدّیتی (weil, da, obwohl) و جایگاه فعل":{"en":"Causal and opposite sentences (weil, da, obwohl) and the position of the verb","de":"Kausal- und Gegensätze (weil, da, obwohl) und die Position des Verbs"},"جمله‌های موصولی و صفت‌های فاعلی/مفعولی گسترده":{"en":"Relative clauses and extended active/passive adjectives","de":"Relativsätze und erweiterte Aktiv/Passiv-Adjektive"},"حروف ربط دوبخشی و انسجام متن":{"en":"Bipartite conjunctions and text coherence","de":"Bipartite Konjunktionen und Textkohärenz"},"حل انواع سؤالات آزمونی":{"en":"Solve all kinds of test questions","de":"Lösen Sie alle Arten von Testfragen"},"خلاصه‌کردن متن":{"en":"Summarizing the text","de":"Den Text zusammenfassen"},"در Hören، فهم مفهوم مهم‌تر از تعداد دفعات گوش‌دادن است.":{"en":"In Hören, understanding the concept is more important than the number of times you listen.","de":"Beim Hören ist das Verständnis des Konzepts wichtiger als die Häufigkeit, mit der man zuhört."},"در Lesen، پاسخ باید بر اساس شواهد متن باشد.":{"en":"In Lesen, the answer must be based on evidence from the text.","de":"Beim Lesen muss die Antwort auf Beweisen aus dem Text basieren."},"در Schreiben، ساختار و تحلیل اشتباهات الزامی است.":{"en":"In Schreiben, structure and error analysis are required.","de":"Beim Schreiben sind Struktur- und Fehleranalyse gefragt."},"در Sprechen، ضبط و اجرای مجدد باید انجام شود.":{"en":"In Sprechen, recording and playback must be done.","de":"Beim Sprechen müssen Aufnahme und Wiedergabe erfolgen."},"در مقایسه با":{"en":"compared to","de":"im Vergleich zu"},"درک استدلال نویسنده، استخراج اطلاعات و پاسخ‌گویی دقیق به سؤالات.":{"en":"Understanding the author's reasoning, extracting information and answering questions accurately.","de":"Die Argumentation des Autors verstehen, Informationen extrahieren und Fragen genau beantworten."},"درک مفهوم جملات، ارتباط بین اطلاعات و ساختار کلی صحبت، نه صرفاً تشخیص کلمات.":{"en":"Understanding the meaning of sentences, the connection between information and the overall structure of speech, not just recognizing words.","de":"Verstehen der Bedeutung von Sätzen, des Zusammenhangs zwischen Informationen und der Gesamtstruktur der Sprache, nicht nur das Erkennen von Wörtern."},"دو جمله با weil/da و یک جمله با obwohl یا trotzdem درباره موضوع امروز بساز.":{"de":"Bilden Sie zwei Sätze mit weil/da und einen Satz mit obwohl oder trotzdem zum heutigen Thema.","en":"Make two sentences with weil/da and one sentence with obwohl or trotzdem about today's topic."},"دو جمله مجهول و یک جمله با sich lassen یا sein + zu بساز.":{"en":"Make two indefinite sentences and one sentence with sich lassen or sein + zu.","de":"Bilden Sie zwei unbestimmte Sätze und einen Satz mit sich lassen oder sein + zu."},"دو جمله موصولی و یک Partizipialattribut بساز.":{"en":"Make two relative clauses and a Partizipialattribute.","de":"Erstellen Sie zwei Relativsätze und ein Partizipialattribut."},"دو منبع را معرفی کن، نقاط هم‌سو و متناقض را مشخص کن و بگو کدام اطلاعات قابل اعتمادتر است یا چه چیزی کم است.":{"en":"Cite the two sources, identify points of agreement and conflict, and say which information is more reliable or what is lacking.","de":"Zitieren Sie die beiden Quellen, identifizieren Sie Übereinstimmungen und Konflikte und sagen Sie, welche Informationen zuverlässiger sind oder welche fehlen."},"دوشنبه":{"en":"Monday","de":"Montag"},"سنجیدن گزینه‌ها":{"en":"Weigh the options","de":"Wägen Sie die Optionen ab"},"سه استدلال یک شخص را با گفتار غیرمستقیم بازگو کن.":{"en":"Retell three arguments of a person using indirect speech.","de":"Erzählen Sie drei Argumente einer Person in indirekter Sprache noch einmal."},"سه توصیه و یک شرط غیرواقعی درباره موضوع امروز بنویس.":{"en":"Write three recommendations and one unrealistic condition about today's topic.","de":"Schreiben Sie drei Empfehlungen und eine unrealistische Bedingung zum heutigen Thema."},"سه جمله با Funktionsverbgefüge و یک جمله با حرف اضافه Genitiv بنویس.":{"en":"Write three sentences with Funktionsverbgefüge and one sentence with Genitive preposition.","de":"Schreiben Sie drei Sätze mit Funktionsverbgefüge und einen Satz mit Genitivpräposition."},"سه جمله با سه حرف ربط دوبخشی متفاوت بنویس.":{"en":"Write three sentences with three different two-part conjunctions.","de":"Schreiben Sie drei Sätze mit drei verschiedenen zweiteiligen Konjunktionen."},"سه جمله را از سبک فعلی به سبک اسمی تبدیل کن.":{"en":"Change the three sentences from the present tense to the nominative tense.","de":"Wandeln Sie die drei Sätze vom Präsens in den Nominativ um."},"سهم افزایش می‌یابد":{"de":"Der Anteil steigt","en":"The share increases"},"سه‌شنبه":{"de":"Dienstag","en":"Tuesday"},"شناسایی ضعف‌های باقی‌مانده":{"en":"Identify remaining weaknesses","de":"Identifizieren Sie verbleibende Schwachstellen"},"شنبه":{"en":"Saturday","de":"Samstag"},"صحبت (۱۰ دقیقه): نظر شخصی، مزایا و معایب، نتیجه‌گیری.":{"en":"Talk (10 minutes): personal opinion, advantages and disadvantages, conclusion.","de":"Vortrag (10 Minuten): Persönliche Meinung, Vor- und Nachteile, Fazit."},"ضبط روزانه مکالمه":{"en":"Record daily speaking practice","de":"Täglich Sprechübungen aufnehmen"},"ضبط و بررسی (۵ دقیقه): مکث، تکرار، جایگاه فعل، جملات ناقص، ادامه بحث.":{"en":"Recording and review (5 minutes): pause, repetition, verb position, incomplete sentences, continuation of the discussion.","de":"Aufzeichnung und Wiederholung (5 Minuten): Pause, Wiederholung, Verbposition, unvollständige Sätze, Fortsetzung der Diskussion."},"ضبط‌کننده صدا":{"en":"Voice recorder","de":"Diktiergerät"},"فاصله‌های مرور: روز اول، روز بعد، سه روز بعد، هفت روز بعد، چهارده روز بعد. اگر مطلبی فراموش شد، زودتر مرور می‌شود.":{"de":"Überprüfungsintervalle: erster Tag, nächster Tag, drei Tage später, sieben Tage später, vierzehn Tage später. Wenn etwas vergessen wird, wird es früher überprüft.","en":"Review intervals: first day, next day, three days later, seven days later, fourteen days later. If something is forgotten, it will be reviewed sooner."},"لغات باید در قالب جمله و ترکیب کاربردی یاد گرفته شوند.":{"en":"Vocabulary should be learned in the form of sentences and practical combinations.","de":"Vokabeln sollten in Form von Sätzen und praktischen Kombinationen erlernt werden."},"متن منسجم با ساختار روشن و تحلیل اشتباهات.":{"en":"Coherent text with clear structure and error analysis.","de":"Kohärenter Text mit klarer Struktur und Fehleranalyse."},"مجهول و جایگزین‌های مجهول":{"de":"Unbekannte und unbekannte Alternativen","en":"Unknown and unknown alternatives"},"مرور Redemittel (۵)":{"de":"Rezension zu Redemittel (5)","en":"Review of Redemittel (5)"},"مرور اشتباهات گرامری (۵)":{"de":"Überprüfung von Grammatikfehlern (5)","en":"Review of grammar mistakes (5)"},"مرور لغات روز قبل (۵)":{"en":"review the words of the previous day (5)","de":"Wiederholen Sie die Worte des Vortages (5)"},"مرور لغات و ترکیبات (خروجی CSV از «دفتر عبارات»)":{"en":"Browsing words and combinations (CSV output from \"Dictionary\")","de":"Durchsuchen von Wörtern und Kombinationen (CSV-Ausgabe von „Dictionary“)"},"مرور گرامر B2":{"en":"Review B2 grammar","de":"B2-Grammatik wiederholen"},"مشکل را کوتاه خلاصه کن، دو یا سه توصیه مشخص بده و برای هر کدام دلیل بیاور؛ در پایان جمع‌بندی و آرزوی موفقیت.":{"en":"Briefly summarize the problem, give two or three specific recommendations and give reasons for each; At the end of the summary and wish for success.","de":"Fassen Sie das Problem kurz zusammen, geben Sie zwei oder drei konkrete Empfehlungen und begründen Sie diese jeweils. Am Ende die Zusammenfassung und der Wunsch nach Erfolg."},"معیار موفقیت: هر هفته باید بتوانم کاری را انجام دهم که هفته قبل در انجام آن مشکل داشتم.":{"en":"Success criteria: Every week I should be able to do something that I had trouble doing the previous week.","de":"Erfolgskriterium: Jede Woche sollte ich in der Lage sein, etwas zu tun, womit ich in der Vorwoche Probleme hatte."},"مقایسه اطلاعات":{"en":"Compare information","de":"Informationen vergleichen"},"مقدمه و ساختار ارائه را بگو، نکات خواسته‌شده را به ترتیب توضیح بده، یک مثال بزن و با جمع‌بندی تمام کن.":{"en":"State the introduction and structure of the presentation, explain the desired points in order, give an example, and conclude with a summary.","de":"Geben Sie Einleitung und Aufbau der Präsentation an, erläutern Sie der Reihe nach die gewünschten Punkte, nennen Sie ein Beispiel und schließen Sie mit einer Zusammenfassung ab."},"موضوع و منبع متن، دو یا سه اطلاعات اصلی و نتیجه متن را با جملات خودت بگو؛ جزئیات کم‌اهمیت را حذف کن.":{"en":"Say the topic and source of the text, two or three main information and the result of the text in your own sentences; Remove unimportant details.","de":"Sagen Sie in Ihren eigenen Sätzen das Thema und die Quelle des Textes, zwei oder drei Hauptinformationen und das Ergebnis des Textes; Entfernen Sie unwichtige Details."},"نقد اقدامات":{"en":"Criticism of actions","de":"Kritik an Handlungen"},"نقل قول غیرمستقیم – برای «Argumente wiedergeben»":{"de":"Indirektes Zitat – für „Argumente wiedergeben“","en":"Indirect quote – for \"Argumente wiedergeben\""},"نمودار نشان می‌دهد":{"de":"Das Diagramm zeigt","en":"The diagram shows"},"نمونه آزمون رسمی":{"en":"Official exam sample","de":"Offizielle Prüfungsprobe"},"نوشتن متن‌های کوتاه (حداقل ۱۵۰ کلمه)":{"en":"Writing short texts (at least 150 words)","de":"Schreiben kurzer Texte (mindestens 150 Wörter)"},"نوشتن متن‌های ۲۰۰ کلمه‌ای":{"en":"Writing texts of 200 words","de":"Schreiben von Texten mit 200 Wörtern"},"هر هفته عملکرد باید با هفته قبل مقایسه شود.":{"en":"Each week performance should be compared with the previous week.","de":"Die Leistung jeder Woche sollte mit der Vorwoche verglichen werden."},"هر گزینه را با یک مزیت و یک عیب معرفی کن، معیار تصمیم را بگو و با دلیل یک گزینه را انتخاب کن.":{"en":"Introduce each option with an advantage and a disadvantage, tell the decision criteria and choose an option with a reason.","de":"Stellen Sie jede Option mit Vor- und Nachteilen vor, nennen Sie die Entscheidungskriterien und wählen Sie eine Option mit Begründung aus."},"هفته ۱ و ۲":{"en":"Week 1 and 2","de":"Woche 1 und 2"},"هفته ۳ تا ۶":{"en":"Week 3 to 6","de":"Woche 3 bis 6"},"وجه التزامی دوم: توصیه، فرض غیرواقعی، درخواست مؤدبانه":{"en":"Second imperative: recommendation, unrealistic assumption, polite request","de":"Zweiter Imperativ: Empfehlung, unrealistische Annahme, höfliche Bitte"},"پادکست آلمانی (مثلاً Deutschlandfunk, DW «Langsam gesprochene Nachrichten»)":{"en":"German podcast (e.g. Deutschlandfunk, DW \"Langsam gesprochene Nachrichten\")","de":"Deutscher Podcast (z.B. Deutschlandfunk, DW „Langsam gesprochene Nachrichten“)"},"پنجشنبه":{"en":"Thursday","de":"Donnerstag"},"چهار مهارت":{"en":"Four skills","de":"Vier Fähigkeiten"},"چهارشنبه":{"de":"Mittwoch","en":"Wednesday"},"گرامر و واژگان":{"en":"Grammar and vocabulary","de":"Grammatik und Wortschatz"},"یادگیری لغت در قالب ترکیب و جمله.":{"en":"Learning words in the form of combinations and sentences.","de":"Wörter in Form von Kombinationen und Sätzen lernen."},"یکشنبه":{"de":"Sonntag","en":"Sunday"},"۱۰ دقیقه: پنج لغت جدید (Artikel, Plural, معنی, Wortart, ۵ ترکیب, جمله نمونه, Perfekt)":{"en":"10 minutes: five new words (Artikel, Plural, meaning, Wortart, 5 combinations, sample sentence, Perfekt)","de":"10 Minuten: fünf neue Wörter (Artikel, Plural, Bedeutung, Wortart, 5 Kombinationen, Beispielsatz, Perfekt)"},"۲ فعالیت":{"en":"2 activities","de":"2 Aktivitäten"},"۳۰ سؤال":{"en":"30 questions","de":"30 Fragen"},"۳۴ سؤال":{"de":"34 Fragen","en":"34 questions"},"۳۵ دقیقه":{"de":"35 Minuten","en":"35 minutes"},"۴۰ دقیقه":{"de":"40 Minuten","en":"40 minutes"},"۵ دقیقه: مرور لغات قبلی بدون نگاه به جزوه":{"en":"5 minutes: reviewing the previous words without looking at the booklet","de":"5 Minuten: Wiederholen Sie die vorherigen Wörter, ohne das Heft anzusehen"},"۵ دقیقه: پنج Redemittel":{"en":"5 minutes: Five Redemittel","de":"5. Minute: Fünf Redemittel"},"۵ دقیقه: پنج جمله (حداقل دو جمله با گرامر هفته)":{"en":"5 minutes: five sentences (at least two sentences with the grammar of the week)","de":"5 Minuten: fünf Sätze (mindestens zwei Sätze mit der Grammatik der Woche)"},"۵۵ دقیقه":{"en":"55 minutes","de":"55 Minuten"},"۶۰ دقیقه":{"de":"60 Minuten","en":"60 minutes"},"۷ فعالیت":{"en":"7 activities","de":"7 Aktivitäten"}};
